"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import type { ReferenceCatalogRecord } from "../src/application/reference-catalog-contract";
import type { ReferenceMelodyClass } from "../src/application/reference-melody";
import {
  isOutsideReferenceMelodyClass,
  resolveReferenceMelodyEdgeEditorMode,
} from "../src/application/reference-melody-edge-editor";
import type { RecommendedReferenceSong } from "../src/application/reference-antiphon-recommendation";
import { ReferenceSongLookupField } from "./reference-song-lookup-field";
import { GuidePanelHelpButton } from "./guide-panel-help-button";

type EditorResult<T> =
  | { success: true; value: T }
  | { success: false; error: { message: string } };

type EdgeResult = EditorResult<{ exists: boolean }>;
type MelodyResult = EditorResult<ReferenceMelodyClass>;

export type ReferenceMelodyEdgeEditorProps = {
  getMelodyClass: (referenceSongId: string) => Promise<MelodyResult>;
  getMelodyEdge: (referenceSongId: string, otherReferenceSongId: string) => Promise<EdgeResult>;
  addMelodyEdge: (referenceSongId: string, otherReferenceSongId: string) => Promise<MelodyResult>;
  removeMelodyEdge: (referenceSongId: string, otherReferenceSongId: string) => Promise<MelodyResult>;
  onChanged: () => void | Promise<void>;
};

type SongLanguage = "czech" | "polish";

function lookupSelection(record: ReferenceCatalogRecord | null): RecommendedReferenceSong | null {
  return record ? {
    referenceSongId: record.id,
    language: record.language,
    canonicalNumber: record.canonicalNumber,
    displayNumber: record.displayNumber,
    title: record.title,
  } : null;
}

export function ReferenceMelodyEdgeEditor({
  getMelodyClass,
  getMelodyEdge,
  addMelodyEdge,
  removeMelodyEdge,
  onChanged,
}: ReferenceMelodyEdgeEditorProps) {
  const [firstLanguage, setFirstLanguage] = useState<SongLanguage>("czech");
  const [secondLanguage, setSecondLanguage] = useState<SongLanguage>("czech");
  const [firstSong, setFirstSong] = useState<ReferenceCatalogRecord | null>(null);
  const [secondSong, setSecondSong] = useState<ReferenceCatalogRecord | null>(null);
  const [firstClass, setFirstClass] = useState<ReferenceMelodyClass>();
  const [secondClass, setSecondClass] = useState<ReferenceMelodyClass>();
  const [edgeExists, setEdgeExists] = useState<boolean>();
  const [firstClassLoading, setFirstClassLoading] = useState(false);
  const [secondClassLoading, setSecondClassLoading] = useState(false);
  const [edgeLoading, setEdgeLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [firstClassError, setFirstClassError] = useState<string>();
  const [secondClassError, setSecondClassError] = useState<string>();
  const [edgeError, setEdgeError] = useState<string>();
  const [mutationError, setMutationError] = useState<string>();
  const firstClassRequest = useRef(0);
  const secondClassRequest = useRef(0);
  const edgeRequest = useRef(0);

  const firstClassMemberIds = useMemo(
    () => firstClass ? new Set(firstClass.members.map((member) => member.referenceSongId)) : undefined,
    [firstClass],
  );
  const secondClassMemberIds = useMemo(
    () => secondClass ? new Set(secondClass.members.map((member) => member.referenceSongId)) : undefined,
    [secondClass],
  );
  const classLoading = firstClassLoading || secondClassLoading;
  const classError = firstClassError ?? secondClassError;

  useEffect(() => {
    const token = ++firstClassRequest.current;
    setFirstClass(undefined);
    setFirstClassError(undefined);
    setFirstClassLoading(false);
    if (!firstSong) return;

    setFirstClassLoading(true);
    void getMelodyClass(firstSong.id).then((result) => {
      if (firstClassRequest.current !== token) return;
      if (result.success) setFirstClass(result.value);
      else setFirstClassError(result.error.message);
    }).catch((cause: unknown) => {
      if (firstClassRequest.current === token) {
        setFirstClassError(cause instanceof Error ? cause.message : "Melody class could not be loaded.");
      }
    }).finally(() => {
      if (firstClassRequest.current === token) setFirstClassLoading(false);
    });
  }, [firstSong?.id]);

  useEffect(() => {
    const token = ++secondClassRequest.current;
    setSecondClass(undefined);
    setSecondClassError(undefined);
    setSecondClassLoading(false);
    if (!secondSong) return;

    setSecondClassLoading(true);
    void getMelodyClass(secondSong.id).then((result) => {
      if (secondClassRequest.current !== token) return;
      if (result.success) setSecondClass(result.value);
      else setSecondClassError(result.error.message);
    }).catch((cause: unknown) => {
      if (secondClassRequest.current === token) {
        setSecondClassError(cause instanceof Error ? cause.message : "Melody class could not be loaded.");
      }
    }).finally(() => {
      if (secondClassRequest.current === token) setSecondClassLoading(false);
    });
  }, [secondSong?.id]);

  useEffect(() => {
    const token = ++edgeRequest.current;
    setEdgeExists(undefined);
    setEdgeError(undefined);
    setMutationError(undefined);
    setEdgeLoading(false);

    if (!firstSong || !secondSong || firstSong.id === secondSong.id) return;

    setEdgeLoading(true);
    void getMelodyEdge(firstSong.id, secondSong.id).then((result) => {
      if (edgeRequest.current !== token) return;
      if (result.success) setEdgeExists(result.value.exists);
      else setEdgeError(result.error.message);
    }).catch((cause: unknown) => {
      if (edgeRequest.current === token) {
        setEdgeError(cause instanceof Error ? cause.message : "Melody edge state could not be loaded.");
      }
    }).finally(() => {
      if (edgeRequest.current === token) setEdgeLoading(false);
    });
  }, [firstSong?.id, secondSong?.id]);

  const mode = resolveReferenceMelodyEdgeEditorMode(firstSong?.id, secondSong?.id, edgeExists);

  async function refreshEditorState() {
    if (!firstSong || !secondSong || firstSong.id === secondSong.id) return;
    const [nextFirstClass, nextSecondClass, nextEdge] = await Promise.all([
      getMelodyClass(firstSong.id),
      getMelodyClass(secondSong.id),
      getMelodyEdge(firstSong.id, secondSong.id),
    ]);
    if (nextFirstClass.success) {
      setFirstClass(nextFirstClass.value);
      setFirstClassError(undefined);
    } else {
      setFirstClassError(nextFirstClass.error.message);
    }
    if (nextSecondClass.success) {
      setSecondClass(nextSecondClass.value);
      setSecondClassError(undefined);
    } else {
      setSecondClassError(nextSecondClass.error.message);
    }
    if (nextEdge.success) {
      setEdgeExists(nextEdge.value.exists);
      setEdgeError(undefined);
    } else {
      setEdgeExists(undefined);
      setEdgeError(nextEdge.error.message);
    }
  }

  async function mutate(action: "add" | "remove") {
    if (!firstSong || !secondSong || saving || mode !== action) return;
    setSaving(true);
    setMutationError(undefined);
    try {
      const result = action === "add"
        ? await addMelodyEdge(firstSong.id, secondSong.id)
        : await removeMelodyEdge(firstSong.id, secondSong.id);
      if (!result.success) {
        setMutationError(result.error.message);
        return;
      }
      await Promise.all([refreshEditorState(), onChanged()]);
    } catch (cause) {
      setMutationError(cause instanceof Error ? cause.message : "Melody edge could not be changed.");
    } finally {
      setSaving(false);
    }
  }

  return <fieldset className="field-group catalog-melody-edge-editor" aria-label="Melody edge editor" data-guide-hint-scope="catalog.melody-edges">
    <GuidePanelHelpButton scope="catalog.melody-edges" label="Melody edges help" />
    <legend>Melody edges</legend>

    <div className="catalog-melody-edge-language-row">
      <select
        aria-label="First song language"
        data-guide-hint="catalog.melody.language"
        value={firstLanguage}
        onChange={(event) => {
          setFirstLanguage(event.target.value as SongLanguage);
          setFirstSong(null);
        }}
      >
        <option value="czech">Czech</option>
        <option value="polish">Polish</option>
      </select>
      <select
        aria-label="Second song language"
        data-guide-hint="catalog.melody.language"
        value={secondLanguage}
        onChange={(event) => {
          setSecondLanguage(event.target.value as SongLanguage);
          setSecondSong(null);
        }}
      >
        <option value="czech">Czech</option>
        <option value="polish">Polish</option>
      </select>
    </div>

    <div className="catalog-melody-edge-song-row">
      <MelodyEdgeSongLookup
        side="first"
        language={firstLanguage}
        selected={firstSong}
        optionClassName={(record) => isOutsideReferenceMelodyClass(record.id, secondSong?.id, secondClassMemberIds)
          ? "reference-song-option-outside-melody"
          : undefined}
        onSelect={setFirstSong}
      />
      <MelodyEdgeSongLookup
        side="second"
        language={secondLanguage}
        selected={secondSong}
        optionClassName={(record) => isOutsideReferenceMelodyClass(record.id, firstSong?.id, firstClassMemberIds)
          ? "reference-song-option-outside-melody"
          : undefined}
        onSelect={setSecondSong}
      />
    </div>

    <div className="catalog-melody-edge-actions" aria-label="Melody edge actions">
      <button
        type="button"
        data-guide-hint="catalog.melody.add"
        disabled={saving || edgeLoading || mode !== "add"}
        onClick={() => void mutate("add")}
      >Add</button>
      <button
        type="button"
        data-guide-hint="catalog.melody.remove"
        disabled={saving || edgeLoading || mode !== "remove"}
        onClick={() => void mutate("remove")}
      >Remove</button>
    </div>

    {mode === "self" && <p className="catalog-candidate-state inline-error" role="alert">A melody edge cannot connect a song to itself.</p>}
    {(classLoading || edgeLoading) && <p className="catalog-candidate-state" role="status">Checking melody structure…</p>}
    {classError && <p className="catalog-candidate-state inline-error" role="alert">{classError}</p>}
    {edgeError && <p className="catalog-candidate-state inline-error" role="alert">{edgeError}</p>}
    {mutationError && <p className="catalog-candidate-state inline-error" role="alert">{mutationError}</p>}
  </fieldset>;
}

function MelodyEdgeSongLookup({
  side,
  language,
  selected,
  optionClassName,
  onSelect,
}: {
  side: "first" | "second";
  language: SongLanguage;
  selected: ReferenceCatalogRecord | null;
  optionClassName?: (record: ReferenceCatalogRecord) => string | undefined;
  onSelect: (record: ReferenceCatalogRecord | null) => void;
}) {
  const label = side === "first" ? "First song" : "Second song";
  return <ReferenceSongLookupField
    language={language}
    selected={lookupSelection(selected)}
    ariaLabel={label}
    listboxId={`melody-edge-${side}-song-listbox`}
    getOptionClassName={optionClassName}
    selectedValueClassName="melody-edge-selected-value"
    guideHint="catalog.melody.song"
    onSelect={onSelect}
  />;
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { DbReferenceCatalogClient } from "../src/application/reference-catalog-client";
import type { ReferenceCatalogRecord } from "../src/application/reference-catalog-contract";
import type { RecommendedReferenceSong } from "../src/application/reference-antiphon-recommendation";

type ReferenceSongLookupClient = Pick<DbReferenceCatalogClient, "list">;

export type ReferenceSongLookupFieldProps = {
  language: "czech" | "polish";
  selected: RecommendedReferenceSong | null;
  disabled?: boolean;
  ariaLabel?: string;
  listboxId?: string;
  getOptionClassName?: (record: ReferenceCatalogRecord) => string | undefined;
  selectedValueClassName?: string;
  guideHint?: string;
  onSelect: (record: ReferenceCatalogRecord | null) => void;
  clientFactory?: () => ReferenceSongLookupClient;
};

const defaultClientFactory = () => new DbReferenceCatalogClient();
const label = (song: RecommendedReferenceSong | null) => song ? `${song.displayNumber} · ${song.title}` : "none";

async function listAll(client: ReferenceSongLookupClient, language: "czech" | "polish", search: string): Promise<ReferenceCatalogRecord[]> {
  const first = await client.list({ language, search, page: 0, pageSize: 200 });
  if (first.pageCount <= 1) return first.records;
  const rest = await Promise.all(
    Array.from({ length: first.pageCount - 1 }, (_, index) =>
      client.list({ language, search, page: index + 1, pageSize: 200 }),
    ),
  );
  return [first, ...rest].flatMap((page) => page.records);
}

export function ReferenceSongLookupField({
  language,
  selected,
  disabled = false,
  ariaLabel = "Ref song",
  listboxId = "reference-song-listbox",
  getOptionClassName,
  selectedValueClassName,
  guideHint,
  onSelect,
  clientFactory = defaultClientFactory,
}: ReferenceSongLookupFieldProps) {
  const client = useMemo(() => clientFactory(), [clientFactory]);
  const wrapperRef = useRef<HTMLDivElement>(null);
  const request = useRef(0);
  const inputWasOpenOnPointerDown = useRef(false);
  const [open, setOpen] = useState(false);
  const [dirty, setDirty] = useState(false);
  const [query, setQuery] = useState("");
  const [records, setRecords] = useState<ReferenceCatalogRecord[]>([]);
  const [activeIndex, setActiveIndex] = useState(0);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string>();

  useEffect(() => {
    setOpen(false);
    setDirty(false);
    setQuery("");
    setRecords([]);
    setActiveIndex(0);
    setError(undefined);
    request.current += 1;
  }, [language]);

  useEffect(() => {
    if (!open) return;
    const token = ++request.current;
    setLoading(true);
    setError(undefined);
    void listAll(client, language, dirty ? query.trim() : "").then((next) => {
      if (request.current !== token) return;
      setRecords(next);
      setActiveIndex((index) => Math.min(index, next.length));
    }).catch((cause: unknown) => {
      if (request.current !== token) return;
      setRecords([]);
      setError(cause instanceof Error ? cause.message : "Reference song lookup failed.");
    }).finally(() => {
      if (request.current === token) setLoading(false);
    });
  }, [client, language, open, dirty, query]);

  useEffect(() => {
    if (!open) return;
    function dismiss(event: PointerEvent) {
      const target = event.target;
      if (!(target instanceof Node) || wrapperRef.current?.contains(target)) return;
      setOpen(false);
      setDirty(false);
      setQuery("");
    }
    document.addEventListener("pointerdown", dismiss, true);
    return () => document.removeEventListener("pointerdown", dismiss, true);
  }, [open]);

  function openLookup() {
    if (disabled || open) return;
    setOpen(true);
    setDirty(false);
    setQuery("");
    setActiveIndex(0);
    queueMicrotask(() => wrapperRef.current?.querySelector<HTMLInputElement>("input")?.select());
  }

  function closeLookup() {
    setOpen(false);
    setDirty(false);
    setQuery("");
    setActiveIndex(0);
  }

  function choose(record: ReferenceCatalogRecord | null) {
    onSelect(record);
    closeLookup();
  }

  function onKeyDown(event: React.KeyboardEvent<HTMLInputElement>) {
    if (event.key === "Escape") {
      if (open) {
        event.preventDefault();
        closeLookup();
      }
      return;
    }
    if (!open && ["ArrowDown", "ArrowUp", "Home", "End"].includes(event.key)) {
      event.preventDefault();
      openLookup();
      return;
    }
    if (!open) return;
    const optionCount = records.length + 1;
    if (event.key === "Home") {
      event.preventDefault();
      setActiveIndex(0);
    } else if (event.key === "End") {
      event.preventDefault();
      setActiveIndex(optionCount - 1);
    } else if (event.key === "ArrowDown") {
      event.preventDefault();
      setActiveIndex((index) => Math.min(optionCount - 1, index + 1));
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      setActiveIndex((index) => Math.max(0, index - 1));
    } else if (event.key === "Enter") {
      event.preventDefault();
      choose(activeIndex === 0 ? null : records[activeIndex - 1] ?? null);
    }
  }

  const displayValue = open && dirty ? query : label(selected);
  return <div className="reference-song-lookup" ref={wrapperRef}>
    <div className="reference-song-control">
      <input
        aria-label={ariaLabel}
        data-guide-hint={guideHint}
        role="combobox"
        aria-autocomplete="list"
        aria-expanded={open}
        aria-controls={open ? listboxId : undefined}
        disabled={disabled}
        className={selected && !(open && dirty) ? selectedValueClassName : undefined}
        value={displayValue}
        onPointerDown={() => { inputWasOpenOnPointerDown.current = open; }}
        onFocus={openLookup}
        onClick={() => {
          if (disabled) return;
          if (inputWasOpenOnPointerDown.current) closeLookup();
          else openLookup();
        }}
        onChange={(event) => {
          if (!open) setOpen(true);
          setDirty(true);
          setQuery(event.target.value);
          setActiveIndex(0);
        }}
        onKeyDown={onKeyDown}
      />
    </div>
    {open && <div id={listboxId} className="reference-song-listbox" role="listbox" aria-label={`${ariaLabel} candidates`}>
      <div
        className={`reference-song-option${activeIndex === 0 ? " reference-song-option-active" : ""}`}
        role="option"
        aria-selected={selected === null}
        onPointerMove={() => setActiveIndex(0)}
        onPointerDown={(event) => { event.preventDefault(); choose(null); }}
      >
        <strong>none</strong>
      </div>
      {loading && <div className="reference-song-list-state" role="status">Loading…</div>}
      {error && <div className="reference-song-list-state reference-song-list-error" role="alert">Reference song lookup unavailable.</div>}
      {!loading && !error && records.length === 0 && <div className="reference-song-list-state">No songs match this lookup.</div>}
      {records.map((record, index) => <div
        key={record.id}
        className={`reference-song-option${activeIndex === index + 1 ? " reference-song-option-active" : ""}${getOptionClassName?.(record) ? ` ${getOptionClassName(record)}` : ""}`}
        role="option"
        aria-selected={selected?.referenceSongId === record.id}
        onPointerMove={() => setActiveIndex(index + 1)}
        onPointerDown={(event) => { event.preventDefault(); choose(record); }}
      >
        <strong>{record.displayNumber}</strong>
        <span>{record.title}</span>
      </div>)}
    </div>}
  </div>;
}

/* Phase 31.21 — minimal Service Context presentation only. */

.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) {
  grid-template-columns: repeat(6, minmax(0, 1fr));
}

/* Date / Time / Language — three equal columns. */
.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > label:nth-of-type(1),
.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > label:nth-of-type(2),
.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > label:nth-of-type(3) {
  grid-column: span 2;
  order: 1;
}

/* Compact visible labels while keeping the more descriptive DOM label text. */
.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > label:nth-of-type(1),
.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > label:nth-of-type(2),
.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > label:nth-of-type(3) {
  font-size: 0;
}

.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > label:nth-of-type(1)::before,
.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > label:nth-of-type(2)::before,
.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > label:nth-of-type(3)::before {
  font-size: 0.9rem;
  line-height: normal;
}

.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > label:nth-of-type(1)::before {
  content: "Date";
}

.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > label:nth-of-type(2)::before {
  content: "Time";
}

.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > label:nth-of-type(3)::before {
  content: "Language";
}

.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > label:nth-of-type(-n + 3) > input,
.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > label:nth-of-type(-n + 3) > select {
  font-size: 1rem;
}

/* Priest / Organist — two equal columns. */
.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > label:nth-of-type(4),
.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > label:nth-of-type(5) {
  grid-column: span 3;
  order: 2;
}

/* Antiphon / Topic — full row with their accepted internal 50:50 grid. */
.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > .service-antiphon-topic-row {
  grid-column: 1 / -1;
  order: 3;
}

/* Service note — full-width final row, visually unlabeled and one input-line high. */
.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > .note-field {
  font-size: 0;
  gap: 0;
  grid-column: 1 / -1;
  order: 4;
  position: relative;
}

.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > .note-field > textarea {
  font-size: 1rem;
  height: 2.65rem;
  min-height: 2.65rem;
  overflow-y: hidden;
  resize: none;
}

/* Phase 31.22: the visible empty-state prompt is concise and as muted as other optional selectors. */
.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > .note-field > textarea::placeholder {
  color: transparent;
  opacity: 0;
}

.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > .note-field:has(> textarea:placeholder-shown)::after {
  color: var(--muted);
  content: "Add service note…";
  font-size: 1rem;
  font-weight: 400;
  left: 0.75rem;
  line-height: normal;
  opacity: 0.62;
  pointer-events: none;
  position: absolute;
  top: 0.65rem;
}

/* Minimal scheme: no persistent helper/status prose beneath Service Context controls. */
.field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > label > .field-help {
  display: none;
}

@media (max-width: 720px) {
  .field-group:not(.catalog-context):has(> .service-antiphon-topic-row) {
    grid-template-columns: minmax(0, 1fr);
  }

  .field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > label,
  .field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > .service-antiphon-topic-row,
  .field-group:not(.catalog-context):has(> .service-antiphon-topic-row) > .note-field {
    grid-column: 1;
  }
}

"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { DbReferenceAntiphonClient, MemoryReferenceAntiphonClient } from "../src/application/reference-antiphon-client";
import type { ReferenceAntiphonProvider, ReferenceAntiphonRecord } from "../src/application/reference-antiphon-contract";
import type { RecommendedReferenceSong, ReferenceAntiphonRecommendation } from "../src/application/reference-antiphon-recommendation";
import type { ReferenceCatalogRecord } from "../src/application/reference-catalog-contract";
import { ServiceContextReferenceAntiphonUiState, type ServiceContextAntiphonSearchSnapshot } from "../src/application/service-context-reference-antiphon-ui-state";
import type { ServiceAntiphonReference, ServiceLanguage } from "../src/planning-lifecycle";
import { ReferenceSongLookupField } from "./reference-song-lookup-field";

type RecommendationResult =
  | { success: true; value: ReferenceAntiphonRecommendation }
  | { success: false; error: { message: string } };

export type AntiphonRecommendationClient = {
  get: (antiphonId: string) => Promise<RecommendationResult>;
  set?: (antiphonId: string, referenceSongId: string | null) => Promise<RecommendationResult>;
};

export type ServiceContextReferenceAntiphonFieldProps = {
  runtime: "memory" | "db";
  editable: boolean;
  contextKey: string;
  serviceLanguage: ServiceLanguage;
  selected?: ServiceAntiphonReference;
  recommendedSong?: RecommendedReferenceSong | null;
  recommendationLoading?: boolean;
  recommendationError?: string;
  recommendationClient?: AntiphonRecommendationClient;
  canEditRecommendation?: boolean;
  invalid?: boolean;
  onChange: (value: ServiceAntiphonReference | undefined) => void;
  onRecommendationChanged?: (value: ReferenceAntiphonRecommendation) => void | Promise<void>;
  clientFactory?: (runtime: "memory" | "db") => Pick<ReferenceAntiphonProvider, "list">;
};

type DetailState = {
  antiphon: ServiceAntiphonReference;
  origin: "selected" | "list";
};

type DetailViewState = {
  antiphon: ServiceAntiphonReference;
  origin: "selected" | "list";
  recommendation?: ReferenceAntiphonRecommendation;
  loading: boolean;
  saving: boolean;
  error?: string;
  editableRecommendation: boolean;
};

type ViewProps = {
  editable: boolean;
  selected?: ServiceAntiphonReference;
  invalid?: boolean;
  open: boolean;
  detail?: DetailViewState;
  dirty: boolean;
  query: string;
  snapshot: ServiceContextAntiphonSearchSnapshot;
  activeIndex: number;
  serviceLanguage?: ServiceLanguage;
  onOpen: () => void;
  onInputPointerDown?: () => void;
  onInputClick?: () => void;
  onQueryChange: (value: string) => void;
  onKeyDown: (event: React.KeyboardEvent<HTMLInputElement>) => void;
  onSelect: (record: ReferenceAntiphonRecord) => void;
  onSelectNone: () => void;
  onOpenDetail: (record: ServiceAntiphonReference, origin: "selected" | "list") => void;
  onActiveIndexChange: (index: number) => void;
  onSaveRecommendation: (record: ReferenceCatalogRecord | null) => void;
};

type AntiphonNavigationKey = "ArrowDown" | "ArrowUp" | "Home" | "End";

export function moveAntiphonActiveIndex(currentIndex: number, recordCount: number, key: AntiphonNavigationKey): number {
  if (recordCount <= 0) return 0;
  if (key === "Home") return 0;
  if (key === "End") return recordCount - 1;
  if (key === "ArrowDown") return Math.min(currentIndex + 1, recordCount - 1);
  return Math.max(currentIndex - 1, 0);
}

export function serviceContextLookupInputClickAction(wasOpenOnPointerDown: boolean): "open" | "close" {
  return wasOpenOnPointerDown ? "close" : "open";
}

const label = (selected?: ServiceAntiphonReference) => selected ? `${selected.displayNumber} · ${selected.title}` : "";

export function mixedServiceCandidateStyle(serviceLanguage: ServiceLanguage | undefined, language: "czech" | "polish") {
  if (serviceLanguage !== "mixed") return undefined;
  return {
    background: language === "polish"
      ? "linear-gradient(90deg, #ffffff 0%, #eef0f3 100%)"
      : "linear-gradient(90deg, #eef0f3 0%, #ffffff 100%)",
  };
}

function recordSnapshot(record: ReferenceAntiphonRecord): ServiceAntiphonReference {
  return {
    id: record.id,
    displayNumber: record.displayNumber,
    title: record.title,
    ...(record.sourceUrl ? { sourceUrl: record.sourceUrl } : {}),
  };
}

function antiphonOptionId(record: ReferenceAntiphonRecord): string {
  return `service-antiphon-option-${record.id.replace(/[^a-zA-Z0-9_-]/g, "-")}`;
}

function detailLanguage(antiphon: ServiceAntiphonReference): "czech" | "polish" {
  return antiphon.id.startsWith("polish:") ? "polish" : "czech";
}

export function ServiceContextReferenceAntiphonFieldView(props: ViewProps) {
  const displayValue = props.open && props.dirty ? props.query : label(props.selected);
  const confirmedInvalid = Boolean(props.invalid && !(props.open && props.dirty));
  const activeRecord = props.activeIndex > 0 ? props.snapshot.records[props.activeIndex - 1] : undefined;
  const activeDescendant = props.open
    ? props.activeIndex === 0
      ? "service-antiphon-option-none"
      : activeRecord
        ? antiphonOptionId(activeRecord)
        : undefined
    : undefined;
  const showSelectedDetailButton = Boolean(props.selected && !(props.open && props.dirty));

  return <>
    <div className={`service-antiphon-control${confirmedInvalid ? " service-antiphon-control-invalid" : ""}`}>
      <input
        aria-label="Antiphon"
        role="combobox"
        aria-autocomplete="list"
        aria-expanded={props.open}
        aria-controls={props.open ? "service-antiphon-listbox" : undefined}
        aria-activedescendant={activeDescendant}
        aria-invalid={confirmedInvalid || undefined}
        readOnly={!props.editable}
        value={displayValue}
        placeholder="Select antiphon"
        onPointerDown={props.onInputPointerDown}
        onFocus={props.onOpen}
        onClick={props.onInputClick ?? props.onOpen}
        onChange={(event) => props.onQueryChange(event.target.value)}
        onKeyDown={props.onKeyDown}
      />
      {showSelectedDetailButton && <button
        type="button"
        className="candidate-inline-detail service-antiphon-detail-button"
        aria-expanded={props.detail?.origin === "selected" && props.detail.antiphon.id === props.selected?.id}
        aria-label={`Show antiphon detail for ${props.selected!.displayNumber} ${props.selected!.title}`}
        onPointerDown={(event) => event.preventDefault()}
        onClick={() => props.onOpenDetail(props.selected!, "selected")}
      >Detail</button>}
    </div>

    {props.open && <div id="service-antiphon-listbox" className="service-antiphon-listbox" role="listbox" aria-label="Antiphon candidates">
      <div
        id="service-antiphon-option-none"
        className={`service-antiphon-option service-context-none-option${props.activeIndex === 0 ? " service-antiphon-option-active" : ""}`}
        role="option"
        aria-selected={!props.selected}
        onPointerMove={() => props.onActiveIndexChange(0)}
        onPointerDown={(event) => { event.preventDefault(); props.onSelectNone(); }}
      >
        <span>None</span>
      </div>
      {props.snapshot.loading && <div className="service-antiphon-list-state" role="status">Loading…</div>}
      {props.snapshot.error && <div className="service-antiphon-list-state service-antiphon-list-error" role="alert">Antiphon lookup unavailable.</div>}
      {!props.snapshot.loading && !props.snapshot.error && props.snapshot.records.length === 0 && <div className="service-antiphon-list-state">No antiphons available.</div>}
      {props.snapshot.records.map((record, index) => <div
        id={antiphonOptionId(record)}
