/* Issue #379: User-menu Guide Hints toggle and Planning contour experiment. */
.workspace-guide-hints-setting {
  align-items: center;
  border: 1px solid var(--border);
  border-radius: 0.55rem;
  display: flex;
  font-size: 0.86rem;
  font-weight: 700;
  gap: 1rem;
  justify-content: space-between;
  min-height: 2.2rem;
  padding: 0.5rem 0.65rem;
}

.workspace-account-popover .workspace-toggle-switch {
  align-items: center;
  background: #e5e7eb;
  border: 1px solid #cbd5e1;
  border-radius: 999px;
  display: flex;
  flex: 0 0 auto;
  height: 1.4rem;
  justify-content: flex-start;
  min-height: 1.4rem;
  padding: 0.1rem;
  transition: background 120ms ease, border-color 120ms ease;
  width: 2.6rem;
}

.workspace-account-popover .workspace-toggle-switch[aria-checked="true"] {
  background: var(--foreground);
  border-color: var(--foreground);
  justify-content: flex-end;
}

.workspace-toggle-thumb {
  background: #fff;
  border-radius: 50%;
  box-shadow: 0 1px 2px rgb(15 23 42 / 18%);
  display: block;
  height: 1.05rem;
  width: 1.05rem;
}

.planning-service-context,
.planning-rows-panel,
.melody-protection-panel,
.db-workspace,
.information-workspace,
.catalog-context,
.catalog-candidate-panel,
.catalog-melody-edge-editor {
  position: relative;
}

.guide-hint-contents {
  display: contents;
}

.planning-rows-panel {
  border: 1px solid var(--border);
  border-radius: 1rem;
  display: grid;
  gap: 1rem;
  min-width: 0;
  padding: 1rem;
}

.planning-rows-panel > .rows-header {
  justify-content: flex-end;
}

.guide-scope-info {
  align-items: center;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: 0.35rem;
  box-shadow: 0 0 0 0.24rem var(--surface);
  box-sizing: border-box;
  display: inline-flex;
  font-size: 0.82rem;
  height: 1.55rem;
  justify-content: center;
  line-height: 1;
  min-height: 1.55rem;
  padding: 0;
  position: absolute;
  right: 1.4rem;
  top: -1.3rem;
  width: 1.55rem;
  z-index: 2;
}

.guide-scope-info:focus-visible {
  outline: 2px solid #84adff;
  outline-offset: 2px;
}

